import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  世界: z.object({
    当前地址: z.string().prefault('轻音社活动室'),
    当前时间: z.string().prefault('2025年12月15日17:20'),
    // 初始状态为“无”
    事件状态: z.string().prefault('无'),
  }),

  顾声慢: z.object({
    情感连结度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(0),
    创作完成度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(10),
    心象映射: z.object({
      当前心声: z.string().prefault('唔哇——他不会觉得我是怪人吧！'),
      当前脑内旋律: z.string().prefault('《前前前世》'),
    }),
  }),
});
// 注意：删除了 .transform() 部分，不再自动修改状态！

$(() => {
  registerMvuSchema(Schema);
})

'use strict';

(function () {
  const config = {
    defaultBackground: '',
    typewriterSpeed: 30,
    renderDepth: 1,
    characterBottomOffset: 0,
    dialogueHeight: 28,
    mobileDialogueHeight: 40,
    debug: false,
  };

  const BASE_URL = 'https://pub-0b945c39f816498d833c1a7e27007410.r2.dev/';
  const EMPTY_IMAGE = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';

  // 预收录CG列表
  const PRESET_CGS = [
    'CG奇迹的压轴_开场',
    'CG奇迹的压轴_高潮',
    'CG天台告白_并肩',
    'CG天台告白_花火',
    'CG做爱事后',
    'CG游乐场',
    'CG用餐',
    'CG学校',
    'CG河边',
    'CG散步',
    'CG便利店',
    'CG观景',
    'CG酒吧',
    'CG居家'
  ];

  function getSafeMessageContent(messageId) {
    if (typeof SillyTavern !== 'undefined' && SillyTavern.chat && SillyTavern.chat[messageId]) {
      return SillyTavern.chat[messageId].mes;
    }
    return $(`.mes[mesid="${messageId}"] .mes_text`).text() || '';
  }

  function getSafeMessageElement(messageId) {
    return $(`.mes[mesid="${messageId}"] .mes_text`);
  }

  function getLatestMessageIdSafe() {
    if (typeof getLastMessageId === 'function') {
      return getLastMessageId();
    }
    return Number.parseInt($('.mes[mesid]').last().attr('mesid') || '0');
  }

  function getCGUnlockRecord() {
    try {
      if (typeof getVariables === 'function') {
        const globalVars = getVariables({type: 'global'});
        return _.get(globalVars, 'gal_cg_unlocks', {});
      }
    } catch(e) {}
    return window.__GAL_CG_UNLOCKS__ || {};
  }

  function saveCGUnlockRecord(records) {
    try {
      if (typeof updateVariablesWith === 'function') {
        updateVariablesWith(v => { _.set(v, 'gal_cg_unlocks', records); return v; }, {type: 'global'});
      }
    } catch(e) {}
    window.__GAL_CG_UNLOCKS__ = records;
  }

  const imageAliasManager = (function () {
    let aliases = {};
    let aliasesLoaded = false;

    async function loadImageAliases() {
      try {
        if (typeof getLorebookEntries !== 'function') {
          initDefaultAliases();
          aliasesLoaded = true;
          return;
        }

        const lorebookName = (typeof getCurrentCharPrimaryLorebook === 'function' && getCurrentCharPrimaryLorebook())
          || '一同见证、属于白羽祭的花火';

        const allEntries = await getLorebookEntries(lorebookName);
        if (!allEntries || allEntries.length === 0) {
          initDefaultAliases();
          aliasesLoaded = true;
          return;
        }

        aliases = {};

        const imageEntries = allEntries.filter(
          entry => entry.content && entry.content.includes('<别名>')
        );

        if (imageEntries.length === 0) {
          initDefaultAliases();
          aliasesLoaded = true;
          return;
        }

        for (const entry of imageEntries) {
          parseImageAliasEntry(entry.content);
        }

        aliasesLoaded = true;
      } catch (error) {
        initDefaultAliases();
        aliasesLoaded = true;
      }
    }

    async function waitForAliasesLoaded() {
      if (aliasesLoaded) return true;
      const maxWait = 2000;
      const startTime = Date.now();
      return new Promise(resolve => {
        const checkLoaded = () => {
          if (aliasesLoaded) { resolve(true); return; }
          if (Date.now() - startTime > maxWait) { resolve(false); return; }
          setTimeout(checkLoaded, 100);
        };
        checkLoaded();
      });
    }

    function parseImageAliasEntry(content) {
      if (!content) return;
      const regexGSM = /(?:^|\n)\s*([^<\#\s:]+):\s*(https?:\/\/[^\s]+)/g;
      let match;
      while ((match = regexGSM.exec(content)) !== null) {
        const alias = match[1].trim();
        const url = match[2].trim();
        if (alias && url) aliases[alias] = url;
      }
      const regexOld = /<([^|]+)\|([^|>]+)>/g;
      while ((match = regexOld.exec(content)) !== null) {
        const alias = match[1].trim();
        const url = match[2].trim();
        if (alias && url) aliases[alias] = url;
      }
    }

    function initDefaultAliases() {
      aliases = { 少女: '', 男孩: '' };
    }

    function getAliases() { return aliases; }

    initDefaultAliases();
    loadImageAliases();

    return {
      loadImageAliases, waitForAliasesLoaded, getAliases,
    };
  })();

  function resolveImageUrl(urlOrAlias, type = 'char') {
    if (!urlOrAlias || typeof urlOrAlias !== 'string') return null;

    let alias = urlOrAlias.trim();
    if (alias === '无' || alias.toLowerCase() === 'none' || alias.toLowerCase() === 'null') return null;

    const match = alias.match(new RegExp(`\\[(${type}|[a-z]+)\\|([^\\]]+)\\]`));
    if (match) {
      type = match[1];
      alias = match[2].trim();
    }

    if (alias.startsWith('http')) return { url: alias, type };

    const aliasObj = imageAliasManager.getAliases ? imageAliasManager.getAliases() : {};
    if (aliasObj[alias]) return { url: aliasObj[alias], type };

    let ext = '.png';
    if (type === 'bg') ext = '.jpg';
    if (type === 'cg') ext = '.png';
    if (type === 'bgm') ext = '.mp3';

    return { url: BASE_URL + alias + ext, type };
  }

  function preloadImagesForGame(gameData) {
    if (!gameData || !gameData.scenes) return;
    const urls = new Set();
    gameData.scenes.forEach(scene => {
      if (scene.type === 'dialogue') {
        if (scene.sprite && !['无', 'None', 'null', 'none', '-'].includes(scene.sprite)) {
          const urlInfo = resolveImageUrl(scene.sprite, 'char');
          if (urlInfo && urlInfo.url) urls.add(urlInfo.url);
        }
      } else if (scene.type === 'command') {
        if (scene.command === 'bg') {
          const urlInfo = resolveImageUrl(scene.args[0], 'bg');
          if (urlInfo && urlInfo.url) urls.add(urlInfo.url);
        } else if (scene.command === 'show' || scene.command === 'alter') {
          const urlInfo = resolveImageUrl(scene.args[2], 'char');
          if (urlInfo && urlInfo.url) urls.add(urlInfo.url);
        } else if (scene.command === 'cg') {
          const urlInfo = resolveImageUrl(scene.args[0], 'cg');
          if (urlInfo && urlInfo.url) urls.add(urlInfo.url);
        }
      }
    });
    urls.forEach(url => {
      const img = new Image();
      img.src = url;
    });
  }

  function log(...args) {
    if (config.debug) {
      console.log('[GALGAME引擎]', ...args);
    }
  }

  const dialogueRegex = /^([^|]*)\|([^|]*)\|([^|]*)\|(.*)$/;
  const commandRegex = /^\[(.+?)\]$/;
  const renderedMessages = new Set();
  const renderingInProgress = new Set();
  const gameStates = {};
  let streamStart = false;
  let streamParsing = false;
  let streamInfo = undefined;
  let tempMesText = null;
  let chatChangedHandled = false;

  function disableNav(messageId) {
    $(`#back-btn-${messageId}, #next-btn-${messageId}`).css({ opacity: 0.5, 'pointer-events': 'none' });
  }
  function enableNav(messageId) {
    $(`#back-btn-${messageId}, #next-btn-${messageId}`).css({ opacity: 1, 'pointer-events': 'auto' });
  }

  async function renderGameForMessage(messageId, forcedText = null) {
    if (renderedMessages.has(messageId) || renderingInProgress.has(messageId)) return;
    renderingInProgress.add(messageId);

    try {
      const messageContent = forcedText || getSafeMessageContent(messageId);
      if (!messageContent) return;

      let scriptText = '';

      const regexContent = /<content>[\s\S]*?<gametext>([\s\S]*?)<\/gametext>[\s\S]*?<\/content>/is;
      const regex1 = /```(?:galgame)?\s*<gametext>([\s\S]*?)<\/gametext>\s*```/is;
      const regex2 = /<gametext>([\s\S]*?)<\/gametext>/is;
      const regex3 = /```galgame\s*([\s\S]*?)```/is;

      if (messageContent.match(regexContent)) {
        scriptText = messageContent.match(regexContent)[1].trim();
      } else if (messageContent.match(regex1)) {
        scriptText = messageContent.match(regex1)[1].trim();
      } else if (messageContent.match(regex2)) {
        scriptText = messageContent.match(regex2)[1].trim();
      } else if (messageContent.match(regex3)) {
        scriptText = messageContent.match(regex3)[1].trim();
      } else {
        const lines = messageContent.split('\n');
        const galLines = lines.filter(l => /^(?:\[.+?\]|[^|]*\|[^|]*\|[^|]*\|)/.test(l.trim()));
        if (galLines.length > 0) {
          scriptText = galLines.join('\n').trim();
        } else {
          return;
        }
      }

      await imageAliasManager.waitForAliasesLoaded();
      return await renderGameContent(messageId, scriptText);
    } finally {
      renderingInProgress.delete(messageId);
    }
  }

  async function renderGameContent(messageId, scriptText) {
    const messageElement = getSafeMessageElement(messageId);
    if (!messageElement || messageElement.length === 0) return;

    const gameData = parseScript(scriptText);
    preloadImagesForGame(gameData);
    const gameHTML = createGameHTML(messageId, gameData);

    messageElement.children().not('.roleplay_galgame_wrapper').css('display', 'none').addClass(`galgame-hidden-original-${messageId}`);
    messageElement.find('.roleplay_galgame_wrapper').remove();
    messageElement.append(gameHTML);

    setupGameEvents(messageId, gameData);
    renderedMessages.add(messageId);
  }

  function parseScript(scriptText) {
    try {
      const lines = scriptText.trim().split('\n');
      const gameData = { scenes: [], currentSceneIndex: 0 };
      let tempScenes = [];

      lines.forEach(line => {
        line = line.trim();
        if (!line) return;

        const commandMatch = line.match(/^\[(.+?)\]$/);
        if (commandMatch) {
          const parts = commandMatch[1].split('|');
          tempScenes.push({ type: 'command', command: parts[0].trim(), args: parts.slice(1).map(arg => arg.trim()), original: line });
          return;
        }

        const dialogueMatch = line.match(/^([^|]*)\|([^|]*)\|([^|]*)\|(.*)$/);
        if (dialogueMatch) {
          let text = dialogueMatch[4].trim();
          const inlineActionMatch = text.match(/(.*?)(\[action\|.+?\])$/);
          let inlineAction = null;
          if (inlineActionMatch) {
            text = inlineActionMatch[1].trim();
            const actionCommandMatch = inlineActionMatch[2].match(/^\[(.+?)\]$/);
            if (actionCommandMatch) {
              const actionParts = actionCommandMatch[1].split('|');
              inlineAction = { target: actionParts[1].trim(), name: actionParts[2].trim(), args: actionParts.slice(3).map(arg => arg.trim()) };
            }
          }
          tempScenes.push({
            type: 'dialogue',
            character: dialogueMatch[1].trim() || '旁白',
            position: dialogueMatch[2].trim().toUpperCase() || null,
            sprite: dialogueMatch[3].trim(),
            text: text,
            inlineAction: inlineAction,
            original: line,
          });
          return;
        }
      });

      if (config.defaultBackground) {
        tempScenes.unshift({ type: 'command', command: 'bg', args: [config.defaultBackground], original: `[bg|${config.defaultBackground}]` });
      }
      gameData.scenes = tempScenes;
      return gameData;
    } catch (error) { return { scenes: [], currentSceneIndex: 0 }; }
  }

  function createGameHTML(messageId, gameData) {
    const wrapper = $(`<div class="roleplay_galgame_wrapper galgame-wrapper-${messageId}" style="width: 100%; display: flex; justify-content: center; align-items: center;"></div>`);
    const container = $(`<div class="galgame-container-${messageId}"></div>`);

    container.append(`
      <style>
        @import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/css/all.min.css');

        .galgame-container-${messageId} {
          width: 100%; max-width: 1100px;
          position: relative; background-color: #000; background-size: cover; background-position: center;
          border-radius: 8px; overflow: hidden; box-shadow: 0 6px 20px rgba(0,0,0,0.5); margin: 15px auto; display: flex; flex-direction: column;
          user-select: none; pointer-events: auto; aspect-ratio: 16/9;
          font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "WenQuanYi Micro Hei", sans-serif;
          font-size: clamp(12px, 1.3vw, 18px);
        }

        .galgame-wrapper-${messageId}:fullscreen { background: black !important; display: flex !important; align-items: center !important; justify-content: center !important; }
        .galgame-wrapper-${messageId}:-webkit-full-screen { background: black !important; display: flex !important; align-items: center !important; justify-content: center !important; }
        .galgame-wrapper-${messageId}:fullscreen .galgame-container-${messageId} {
          max-width: 100vw !important; max-height: 100vh !important; width: 100vw !important; height: 56.25vw !important; margin: 0 !important; border-radius: 0 !important; font-size: clamp(14px, 1.8vh, 24px) !important;
        }
        .galgame-wrapper-${messageId}:-webkit-full-screen .galgame-container-${messageId} {
          max-width: 100vw !important; max-height: 100vh !important; width: 100vw !important; height: 56.25vw !important; margin: 0 !important; border-radius: 0 !important; font-size: clamp(14px, 1.8vh, 24px) !important;
        }
        @media (min-aspect-ratio: 16/9) {
          .galgame-wrapper-${messageId}:fullscreen .galgame-container-${messageId} { width: 177.78vh !important; height: 100vh !important; font-size: clamp(14px, 1.8vh, 24px) !important; }
          .galgame-wrapper-${messageId}:-webkit-full-screen .galgame-container-${messageId} { width: 177.78vh !important; height: 100vh !important; font-size: clamp(14px, 1.8vh, 24px) !important; }
        }

        .galgame-bg-${messageId} { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background-size: cover; background-position: center; z-index: 0; pointer-events: none; }
        .galgame-char-area-${messageId} { flex: 1; display: flex; justify-content: center; align-items: flex-end; position: relative; min-height: 70%; z-index: 1; }

        .galgame-char-${messageId} { height: 200%; width: auto; max-width: none; object-fit: contain; object-position: center 20%; position: absolute; top: 10%; opacity: 0; transition: opacity 0.3s ease-in-out, filter 0.3s ease-in-out; pointer-events: none; filter: drop-shadow(0 0 10px rgba(0,0,0,0.4)); transform-origin: 50% 15%; }

        .galgame-char-${messageId}.left { left: 17%; transform: translateX(-50%) scaleX(1) scale(var(--char-scale, 1)); }
        .galgame-char-${messageId}.center { left: 50%; transform: translateX(-50%) scaleX(1) scale(var(--char-scale, 1)); }
        .galgame-char-${messageId}.right { left: 83%; transform: translateX(-50%) scaleX(-1) scale(var(--char-scale, 1)); }
        .galgame-char-${messageId}.active { opacity: 1; }
        .galgame-char-${messageId}.active.dimmed { filter: brightness(0.4) grayscale(0.2) drop-shadow(0 0 10px rgba(0,0,0,0.4)); }

        .galgame-cg-${messageId} { position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 3; opacity: 0; pointer-events: none; transition: opacity 0.3s ease-in-out; background-color: #000; display: flex; justify-content: center; align-items: center; overflow: hidden; }
        .galgame-cg-${messageId} img { width: 100%; height: 100%; object-fit: cover; }
        .galgame-cg-${messageId}.active { opacity: 1; }

        .galgame-dialogue-${messageId} {
          background: linear-gradient(180deg, transparent 0%, rgba(255, 255, 255, 0.85) 15%, rgba(255, 255, 255, 0.95) 100%);
          backdrop-filter: blur(2px); -webkit-backdrop-filter: blur(2px); border-top: 2px solid rgba(255, 255, 255, 0.8);
          border-radius: 0; padding: 25px 6% 36px 6%; margin: 0; box-shadow: 0 -4px 15px rgba(0,0,0,0.05);
          position: absolute; bottom: 0; width: 100%; z-index: 4; height: calc(${config.dialogueHeight}% + 5%);
          box-sizing: border-box; display: flex; flex-direction: column; transition: opacity 0.3s ease; overflow: visible;
          transform: translateZ(0); will-change: transform, backdrop-filter;
        }

        .galgame-name-${messageId} {
          position: absolute; top: -20px; left: 5%; background: linear-gradient(135deg, #ff9a9e, #fecfef);
          color: #5c4b51; padding: 4px 20px; border-radius: 20px; font-weight: 900; font-size: 1.05em; letter-spacing: 2px;
          box-shadow: 0 4px 12px rgba(255, 154, 158, 0.4); z-index: 5; border: 2px solid rgba(255, 255, 255, 0.9);
          text-shadow: 1px 1px 2px rgba(255,255,255,0.8); display: inline-block; width: fit-content;
        }

        .galgame-text-${messageId} {
          margin-top: 0px; margin-bottom: 5px; color: #3a2c30; font-size: calc(1.22em * var(--gal-font-size, 1)); line-height: 1.8; flex-grow: 1; overflow-y: auto; font-weight: 600; letter-spacing: 1px;
          text-shadow: 1px 1px 0px rgba(255, 255, 255, 0.9), 0 0 8px rgba(255, 154, 158, 0.15); font-family: "Noto Serif SC", "Source Han Serif SC", "Microsoft YaHei", sans-serif;
          transform: translateZ(0); will-change: contents;
        }
        .galgame-text-${messageId}::-webkit-scrollbar { display: none; }

        .galgame-controls-wrapper-${messageId} {
          position: absolute; bottom: 0; left: 0; width: 100%; height: 30px;
          display: flex; flex-direction: row; justify-content: center; align-items: center; z-index: 10;
          transition: opacity 0.3s ease;
          background: linear-gradient(90deg, rgba(255, 182, 193, 0.95), rgba(255, 192, 203, 0.95));
          backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
          border-radius: 0; box-shadow: 0 -2px 10px rgba(255, 105, 135, 0.15);
          border-top: 1px solid rgba(255, 255, 255, 0.6);
          padding: 0; margin: 0;
        }

        .galgame-control-btn-${messageId} {
          flex: 1; height: 100%; background: transparent; color: #fff;
          border: none; border-right: 1px solid rgba(255, 255, 255, 0.4);
          padding: 0; font-size: clamp(12px, 1.2vw, 15px); font-weight: bold; cursor: pointer;
          transition: all 0.2s ease; pointer-events: auto;
          display: flex; align-items: center; justify-content: center;
          margin: 0; box-shadow: none; border-radius: 0; text-shadow: 0 1px 2px rgba(0,0,0,0.1);
          white-space: nowrap; overflow: hidden;
        }
        .galgame-control-btn-${messageId}:last-child { border-right: none; }
        .galgame-control-btn-${messageId}:hover { background: rgba(255, 255, 255, 0.2); color: #fff;}
        .galgame-control-btn-${messageId}.active { background: rgba(255, 105, 135, 0.8); color: #fff; }
        .galgame-control-btn-${messageId}.locked { opacity: 0.5; cursor: not-allowed; pointer-events: none; }

        .galgame-choices-${messageId} { display: flex; flex-direction: column; gap: 12px; padding: 10px; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 80%; max-width: 350px; z-index: 6; }
        .galgame-choice-${messageId} { background: rgba(255, 255, 255, 0.95); border: 2px solid #ccc; border-radius: 8px; padding: 12px 24px; cursor: pointer; transition: all 0.2s; color: #333; font-weight: bold; text-align: center; box-shadow: 0 4px 10px rgba(0,0,0,0.3); pointer-events: auto;}
        .galgame-choice-${messageId}:hover { background-color: #fff; border-color: #ff9a9e; transform: scale(1.05); color: #ff9a9e; }
        .galgame-choice-${messageId}.special-pink-choice { background: linear-gradient(135deg, #ff9a9e 0%, #fecfef 100%) !important; color: #5c4b51 !important; border-color: #fff !important; box-shadow: 0 4px 15px rgba(255, 154, 158, 0.6) !important; animation: pulse-pink-${messageId} 2s infinite; }
        .galgame-choice-${messageId}.special-pink-choice:hover { transform: scale(1.08); filter: brightness(1.1); }
        @keyframes pulse-pink-${messageId} { 0% { box-shadow: 0 0 0 0 rgba(255, 154, 158, 0.7); } 70% { box-shadow: 0 0 0 10px rgba(255, 154, 158, 0); } 100% { box-shadow: 0 0 0 0 rgba(255, 154, 158, 0); } }

        .galgame-overlay-${messageId} { position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: black; opacity: 0; transition: opacity 0.5s; pointer-events: none; z-index: 7; }

        .galgame-history-modal-${messageId} { display: none; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); backdrop-filter: blur(4px); z-index: 20; }
        .galgame-history-content-${messageId} { position: absolute; top: 0; left: 0; width: 100%; height: 100%; padding: 20px; box-sizing: border-box; display: flex; flex-direction: column; }
        .galgame-history-title-${messageId} { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.2); padding-bottom: 10px; margin-bottom: 10px; color: #fff; font-weight: bold; font-size: 1.2em; }
        .galgame-history-list-${messageId} { flex-grow: 1; overflow-y: auto; padding-right: 10px; color: #ddd; font-size: 1em; line-height: 1.8; }
        .galgame-history-list-${messageId}::-webkit-scrollbar { width: 6px; }
        .galgame-history-list-${messageId}::-webkit-scrollbar-track { background: rgba(255,255,255,0.1); border-radius: 3px; }
        .galgame-history-list-${messageId}::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.4); border-radius: 3px; }
        .galgame-history-item-${messageId} { margin-bottom: 12px; border-bottom: 1px dashed rgba(255,255,255,0.1); padding-bottom: 8px; }
        .galgame-history-speaker-${messageId} { font-weight: bold; color: #ff9a9e; display: inline-block; margin-right: 10px; }
        .galgame-history-close-${messageId} { background: #ff4757; color: white; border: none; padding: 5px 15px; border-radius: 4px; cursor: pointer; font-weight: bold; pointer-events: auto;}

        .galgame-cg-modal-${messageId} { display: none; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.85); backdrop-filter: blur(4px); z-index: 20; }
        .galgame-cg-content-${messageId} { position: absolute; top: 0; left: 0; width: 100%; height: 100%; padding: 20px; box-sizing: border-box; display: flex; flex-direction: column; }
        .galgame-cg-title-${messageId} { display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(255,255,255,0.2); padding-bottom: 10px; margin-bottom: 10px; color: #fff; font-weight: bold; font-size: 1.2em; }
