  function showLocationToast(messageId, locName) {
    if (!locName || locName === '未知地点' || locName === '未知' || locName === 'none' || locName === '无') return;
    const toast = $(`#loc-toast-${messageId}`);
    if (toast.length) {
      toast.text(locName);
      toast.addClass('show');
      if (toast.data('timer')) clearTimeout(toast.data('timer'));
      const timer = setTimeout(() => {
        toast.removeClass('show');
      }, 3000);
      toast.data('timer', timer);
    }
  }

  async function performBack(messageId) {
    const state = gameStates[messageId];
    if (!state || state.showingChoices) return;

    let startIdx = state.currentIndex - 1;

    if (state.isTypewriting) {
        cancelAnimationFrame(state.typeTimer);
        state.isTypewriting = false;
        state.skipTypewriter = false;
        state.typeTimer = null;
        state.typeFunction = null;
        state.processing = false;

        startIdx = state.currentIndex;
    }

    if (state.processing) return;

    let targetIndex = -1;
    let dialogueCount = 0;

    for (let i = startIdx; i >= 0; i--) {
        if (state.data.scenes[i].type === 'dialogue') {
            dialogueCount++;
            if (dialogueCount === 2) {
                targetIndex = i;
                break;
            }
        }
    }

    if (targetIndex === -1) targetIndex = 0;

    state.processing = true;

    hideAllCharacters(messageId);
    hideCG(messageId);
    $(`#bg-${messageId}`).css({'background-image': 'none', 'background-color': '#000'});
    let lastBgm = 'none';

    for (let i = 0; i < targetIndex; i++) {
        const scene = state.data.scenes[i];
        if (scene.type === 'command') {
            switch (scene.command) {
                case 'bg': setBackground(messageId, scene.args[0], scene.args[1], 0); break;
                case 'show': case 'alter': showCharacter(messageId, scene.args[0], scene.args[1]?.toUpperCase(), scene.args[2]); break;
                case 'hide': case 'leave': hideCharacter(messageId, scene.args[0]); break;
                case 'hide_all': hideAllCharacters(messageId); break;
                case 'cg': showCG(messageId, scene.args[0]); break;
                case 'hide_cg': hideCG(messageId); break;
                case 'bgm': lastBgm = scene.args[0]; break;
            }
        } else if (scene.type === 'dialogue') {
            if (scene.character !== '旁白') {
                if (scene.position && scene.sprite && !['无', 'None', 'null', 'none', '-'].includes(scene.sprite)) {
                    showCharacter(messageId, scene.character, scene.position, scene.sprite);
                }
            }
        }
    }

    playBGM(messageId, lastBgm);

    state.currentIndex = targetIndex;
    state.processing = false;
    processNextScene(messageId);
  }

  function setupGameEvents(messageId, gameData) {
