    function updateGSMStatusBar(externalData = null) {
      try {
        let variables = null;

        if (externalData && externalData.stat_data) {
            variables = externalData.stat_data;
        } else if (externalData) {
            variables = externalData;
        }

        if (!variables && typeof Mvu !== 'undefined' && Mvu.getMvuData) {
            try {
                const mvuData = Mvu.getMvuData({ type: 'message', message_id: messageId });
                if (mvuData && mvuData.stat_data) variables = mvuData.stat_data;
            } catch (err) {}
        }

        if (!variables && typeof getVariables === 'function') {
            try {
                const msgVars = getVariables({ type: 'message', message_id: messageId });
                if (msgVars && msgVars.stat_data) variables = msgVars.stat_data;
                else variables = msgVars;
            } catch (err) {}
        }

        if (!variables) {
            variables = {};
            let retries = container.data('retry-mvu') || 0;
            if (retries < 5) {
                container.data('retry-mvu', retries + 1);
                setTimeout(() => updateGSMStatusBar(), 1000);
            }
        } else {
            container.data('retry-mvu', 0);
        }

        const loc = _.get(variables, '世界.当前地址') || '未知地点';
        const time = _.get(variables, '世界.当前时间') || '未知时间';
        const event = _.get(variables, '世界.事件状态') || '无';

        container.find(`#gsm-val-loc-${messageId}`).text(loc);
        container.find(`#gsm-val-time-${messageId}`).text(time);
        container.find(`#gsm-val-event-${messageId}`).text(event);

        const affectionRaw = _.get(variables, '顾声慢.情感连结度');
        const compositionRaw = _.get(variables, '顾声慢.创作完成度');

        const affection = isNaN(Number(affectionRaw)) ? 0 : Number(affectionRaw);
        const composition = isNaN(Number(compositionRaw)) ? 0 : Number(compositionRaw);

        container.find(`#gsm-val-affection-${messageId}`).text(affection);
        container.find(`#gsm-bar-affection-${messageId}`).css('width', Math.min(100, Math.max(0, affection)) + '%');
        container.find(`#gsm-val-composition-${messageId}`).text(composition);
        container.find(`#gsm-bar-composition-${messageId}`).css('width', Math.min(100, Math.max(0, composition)) + '%');

        const voice = _.get(variables, '顾声慢.心象映射.当前心声') || '...';
        const melody = _.get(variables, '顾声慢.心象映射.当前脑内旋律') || '无';

        container.find(`#gsm-val-voice-${messageId}`).text(voice);
        container.find(`#gsm-val-melody-${messageId}`).text(melody);

      } catch (err) {
        log('[状态栏更新报错] 被捕获，防止界面卡死', err);
      }
    }

    if (gameStates[messageId]) {
        gameStates[messageId].updateStatus = updateGSMStatusBar;
    }
    updateGSMStatusBar();

    setTimeout(() => { processNextScene(messageId); }, 100);
