  function playBGM(messageId, bgmUrl) {
    const state = gameStates[messageId];
    const nameEl = $(`#bgm-name-${messageId}`);
    const playPauseBtn = $(`#bgm-playpause-${messageId}`);

    if (bgmUrl === 'stop' || bgmUrl === 'none' || bgmUrl === '无') {
        if (window.__GAL_BGM_AUDIO__) {
            window.__GAL_BGM_AUDIO__.pause();
            window.__GAL_BGM_AUDIO__.src = '';
        }
        nameEl.text('当前无BGM');
        playPauseBtn.text('▶');
        if (state) state.pendingBgm = null;
        return;
    }

    const actualUrl = resolveImageUrl(bgmUrl, 'bgm')?.url || bgmUrl;
    if (actualUrl) {
        if (window.__GAL_BGM_AUDIO__ && window.__GAL_BGM_AUDIO__.src && window.__GAL_BGM_AUDIO__.src.endsWith(actualUrl) && !window.__GAL_BGM_AUDIO__.paused) return;

        if (window.__GAL_BGM_AUDIO__) {
            window.__GAL_BGM_AUDIO__.pause();
        }

        const audio = new Audio(actualUrl);
        audio.loop = true;

        try {
            if (typeof getVariables === 'function') {
                const globalVars = getVariables({type: 'global'});
                const savedVol = _.get(globalVars, 'gal_global_bgm_volume');
                if (savedVol !== undefined) {
                    audio.volume = savedVol;
                }
            }
        } catch(e) {}

        window.__GAL_BGM_AUDIO__ = audio;

        audio.addEventListener('timeupdate', () => {
            if (audio.duration && window.__GAL_BGM_AUDIO__ === audio) {
                const currentSlider = $(`#bgm-progress-${messageId}`);
                if(currentSlider.length) currentSlider.val((audio.currentTime / audio.duration) * 100);
            }
        });

        audio.addEventListener('play', () => {
            if (window.__GAL_BGM_AUDIO__ === audio) playPauseBtn.text('⏸');
        });

        audio.addEventListener('pause', () => {
            if (window.__GAL_BGM_AUDIO__ === audio) playPauseBtn.text('▶');
        });

        nameEl.text('加载中...');

        const playPromise = audio.play();
        if (playPromise !== undefined) {
            playPromise.then(() => {
                nameEl.text(bgmUrl);
                if (state) state.pendingBgm = null;
            }).catch(e => {
                log('[BGM] 自动播放被浏览器拦截，等待用户点击画面恢复');
                nameEl.text(bgmUrl + ' (点击播放)');
                if (state) state.pendingBgm = bgmUrl;
            });
        }
    }
  }

  function handleAutoNext(messageId) {
    const state = gameStates[messageId];
    if (state && state.autoMode && !state.showingChoices && !state.skipping && state.currentIndex < state.data.scenes.length) {
      state.autoTimer = setTimeout(() => {
        if (state.autoMode && !state.processing) {
          processNextScene(messageId);
        }
      }, 1500);
    }
  }

  async function performSkip(messageId) {
    const state = gameStates[messageId];
    if (!state || state.showingChoices) return;

    state.skipping = true;
    state.autoMode = false;
    $(`#auto-btn-${messageId}`).removeClass('active');

    if (state.isTypewriting) {
      if (state.typeTimer) cancelAnimationFrame(state.typeTimer);
      state.isTypewriting = false;
      state.skipTypewriter = false;
      state.typeFunction = null;
    }
    if (state.autoTimer) {
      clearTimeout(state.autoTimer);
      state.autoTimer = null;
    }

    let lastDialogue = null;

    while (state.currentIndex < state.data.scenes.length) {
      const scene = state.data.scenes[state.currentIndex];

      if (scene.type === 'dialogue') {
        lastDialogue = scene;
        const nameElement = $(`#name-${messageId}`);
        if (scene.character === '旁白') {
          nameElement.hide().text('');
        } else {
          nameElement.text(scene.character).show();
          if (scene.position && scene.sprite && !['无', 'None', 'null', 'none', '-'].includes(scene.sprite)) {
            showCharacter(messageId, scene.character, scene.position, scene.sprite);
          } else {
            for (const p in state.characters) {
              if (state.characters[p].name === scene.character) {
                const pos = p === 'L' ? 'left' : p === 'C' ? 'center' : 'right';
                $(`#char-${pos}-${messageId}`).removeClass('dimmed').addClass('active');
                for (const otherP in state.characters) {
                  if (otherP !== p && state.characters[otherP].name) {
                    $(`#char-${otherP === 'L' ? 'left' : otherP === 'C' ? 'center' : 'right'}-${messageId}`).addClass('dimmed');
                  }
                }
                break;
              }
            }
          }
        }
        addToHistory(messageId, scene.character === '旁白' ? '' : scene.character, scene.text);
        state.currentIndex++;

      } else if (scene.type === 'command') {
        if (scene.command === 'choice') {
          renderChoices(messageId, scene.args);
          state.currentIndex++;
          break;
        }
        switch (scene.command) {
          case 'bg':
            await setBackground(messageId, scene.args[0], scene.args[1], 0);
            showLocationToast(messageId, scene.args[0]);
            break;
          case 'show': case 'alter': showCharacter(messageId, scene.args[0], scene.args[1]?.toUpperCase(), scene.args[2]); break;
          case 'hide': case 'leave': hideCharacter(messageId, scene.args[0]); break;
          case 'hide_all': hideAllCharacters(messageId); break;
          case 'cg': showCG(messageId, scene.args[0]); break;
          case 'hide_cg': hideCG(messageId); break;
          case 'bgm': playBGM(messageId, scene.args[0]); break;
          case 'action':
             if (scene.args[1] === 'near' || scene.args[1] === 'away') {
               executeAction(messageId, scene.args[0], scene.args[1], scene.args.slice(2), true);
             }
             break;
        }
        state.currentIndex++;
      } else {
        state.currentIndex++;
      }
    }

    if (lastDialogue) {
      $(`#text-${messageId}`).text(lastDialogue.text);
      const nameElement = $(`#name-${messageId}`);
      if (lastDialogue.character === '旁白') {
        nameElement.hide().text('');
      } else {
        nameElement.text(lastDialogue.character).show();
      }
    }

    state.skipping = false;
    state.processing = false;
    if (!state.showingChoices && state.currentIndex >= state.data.scenes.length) {
      enableNav(messageId);
    }
  }

  function renderChoices(messageId, args) {
    const state = gameStates[messageId];
    state.showingChoices = true;
    disableNav(messageId);
    const choicesContainer = $(`#choices-${messageId}`);
    choicesContainer.empty();
    const choiceOverlay = $(`<div style="position:absolute; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); z-index:4;"></div>`);
    $(`.galgame-container-${messageId}`).append(choiceOverlay);

    // --- 修复：文本特征双重校验与强制剔除机制 ---
    try {
      let variables = null;
      if (typeof Mvu !== 'undefined' && Mvu.getMvuData) {
        try {
          const mvuData = Mvu.getMvuData({ type: 'message', message_id: messageId });
          if (mvuData && mvuData.stat_data) variables = mvuData.stat_data;
        } catch (e) {}
      }
      if (!variables && typeof getVariables === 'function') {
        try {
          const msgVars = getVariables({ type: 'message', message_id: messageId });
          if (msgVars && msgVars.stat_data) variables = msgVars.stat_data;
          else variables = msgVars;
        } catch (e) {}
      }

      if (variables) {
        const comp = Number(_.get(variables, '顾声慢.创作完成度') || 0);
        let ev = _.get(variables, '世界.事件状态') || '无';

        // 核心修复：防止 MVU 变量更新延迟导致拿到上一楼的旧状态
        const fullText = getSafeMessageContent(messageId) || '';
        // 只要这楼的文本里有这些特有指令，就说明剧情已经越过了那个阶段
        const isPlayingBaiyu = fullText.includes('CG奇迹的压轴');
        const isPlayingTiantai = fullText.includes('CG天台告白');

        // 基于文本强制修正延迟状态
        if (isPlayingTiantai) {
            ev = '白羽祭完美演出条件达成';
        } else if (isPlayingBaiyu) {
            ev = '演出结束_等待追逐';
        }

        // 机制1：满100且事件未触发时，强制保留白羽祭选项
        if (comp >= 100 && ev === '无') {
          if (!args.some(c => c.trim() === '登场！白羽祭！')) {
            args.push('登场！白羽祭！');
          }
        } else {
          // 状态不符或剧情已过，强力剔除（防 AI 乱生成）
          args = args.filter(c => c.trim() !== '登场！白羽祭！');
        }

        // 机制2：处于天台告白节点时，排他性锁定天台选项
        if (ev === '演出结束_等待追逐') {
          args = ['和她一起前往天台'];
        } else {
          // 状态不符或剧情已过，强力剔除
          args = args.filter(c => c.trim() !== '和她一起前往天台');
        }

        // 兜底：如果被剔除空了，塞一个默认选项防止卡死
        if (!args || args.length === 0) {
            args = ['继续'];
        }
      }
    } catch(err) {
      if (config.debug) console.log('选项强制保留机制获取变量失败', err);
    }
    // ----------------------------------

    args.forEach(choice => {
      const choiceText = choice.trim();
      const isSpecial = choiceText === '登场！白羽祭！' || choiceText === '和她一起前往天台';
      const choiceElement = $(`<div class="galgame-choice-${messageId} ${isSpecial ? 'special-pink-choice' : ''}">${choiceText}</div>`);

      choiceElement.on('click', async function (e) {
        e.stopPropagation();
        choicesContainer.empty(); choiceOverlay.remove(); state.showingChoices = false;

        if (typeof triggerSlash === 'function') {
          try {
            await triggerSlash(`/send ${choiceText}`);
            await triggerSlash('/trigger');
          } catch (err) {
            if (config.debug) console.log('Slash命令执行失败', err);
          }
        }
        state.currentIndex++; processNextScene(messageId);
      });
      choicesContainer.append(choiceElement);
    });
  }

  function processNextScene(messageId) {
    const state = gameStates[messageId];
    if (!state || window.GALGAME_FINISHING_STREAM || window.GALGAME_EDITING_MESSAGE) return;
    state.processing = true;

    if (state.updateStatus) state.updateStatus();

    $(`#char-left-${messageId}, #char-center-${messageId}, #char-right-${messageId}`).css({'transform': '', 'transform-origin': ''});

    const scene = state.data.scenes[state.currentIndex];

    if (!scene) {
      $(`#text-${messageId}`).text('');
      disableNav(messageId);
      $(`#name-${messageId}`).hide();
      state.processing = false;
      return;
    }

    try {
      if (scene.type === 'dialogue') {
        const nameElement = $(`#name-${messageId}`);
        let isSpeakerOnStage = false;
        let handledByShowCharacter = false;

        if (scene.character === '旁白') {
          nameElement.hide().text('');
        } else {
          nameElement.text(scene.character).show();
          if (scene.position && scene.sprite && !['无', 'None', 'null', 'none', '-'].includes(scene.sprite)) {
            showCharacter(messageId, scene.character, scene.position, scene.sprite);
            handledByShowCharacter = true;
            isSpeakerOnStage = true;
          } else {
            for (const p in state.characters) {
              if (state.characters[p].name === scene.character) {
                const pos = p === 'L' ? 'left' : p === 'C' ? 'center' : 'right';
                $(`#char-${pos}-${messageId}`).removeClass('dimmed').addClass('active');
                isSpeakerOnStage = true;
                for (const otherP in state.characters) {
                  if (otherP !== p && state.characters[otherP].name) {
                    $(`#char-${otherP === 'L' ? 'left' : otherP === 'C' ? 'center' : 'right'}-${messageId}`).addClass('dimmed');
                  }
                }
                break;
              }
            }
          }
        }

        if (!handledByShowCharacter && !isSpeakerOnStage) {
          for (const p in state.characters) {
            if (state.characters[p].name) {
              const pos = p === 'L' ? 'left' : p === 'C' ? 'center' : 'right';
              $(`#char-${pos}-${messageId}`).addClass('dimmed');
            }
          }
        }

        typewriterEffect(messageId, scene.text, () => {
          if (scene.inlineAction) executeAction(messageId, scene.inlineAction.target, scene.inlineAction.name, scene.inlineAction.args);
          state.currentIndex++;
          state.processing = false;
          enableNav(messageId);
        });
      } else if (scene.type === 'command') {
        processCommand(messageId, scene.command, scene.args).then(() => {
          if (state.skipping) return;
          state.currentIndex++;
          state.processing = false;
          if (scene.command !== 'choice') {
            setTimeout(() => {
              if (!state.skipping && !window.GALGAME_FINISHING_STREAM) {
                processNextScene(messageId);
              }
            }, 50);
          }
        });
      } else {
        state.currentIndex++;
        state.processing = false;
        processNextScene(messageId);
      }
    } catch (error) { state.currentIndex++; state.processing = false; }
  }

  async function processCommand(messageId, command, args) {
    const state = gameStates[messageId];
    if (!state) return;
    try {
      switch (command) {
        case 'bg':
          await setBackground(messageId, args[0], args[1], args[2] ? parseFloat(args[2]) : 0.5);
          showLocationToast(messageId, args[0]);
          break;
        case 'show': case 'alter': showCharacter(messageId, args[0], args[1]?.toUpperCase(), args[2]); break;
        case 'hide': case 'leave': hideCharacter(messageId, args[0]); break;
        case 'hide_all': hideAllCharacters(messageId); break;
        case 'cg': showCG(messageId, args[0]); break;
        case 'hide_cg': hideCG(messageId); break;
        case 'bgm': playBGM(messageId, args[0]); break;
        case 'action': executeAction(messageId, args[0], args[1], args.slice(2)); break;
        case 'wait':
          const waitTime = parseFloat(args[0]) * 1000 || 500;
          disableNav(messageId);
          await new Promise(resolve => setTimeout(resolve, waitTime));
          enableNav(messageId);
          break;
        case 'choice':
          renderChoices(messageId, args);
          break;
        case 'effect':
          const effectType = args[0];
          const duration = args[1] ? parseFloat(args[1]) : 0.5;
          const overlay = $(`#overlay-${messageId}`);
          if (effectType === 'screen_flash') {
            overlay.css({ opacity: '0.8', background: 'white', transition: 'opacity 0.1s' });
            await new Promise(resolve => setTimeout(resolve, 100));
            overlay.css({ opacity: '0', transition: 'opacity 0.1s' });
          } else if (effectType === 'fade_to_black') {
            overlay.css({ opacity: '0', background: 'black', transition: `opacity ${duration}s` });
            setTimeout(() => overlay.css('opacity', '1'), 10);
            await new Promise(resolve => setTimeout(resolve, duration * 1000));
          } else if (effectType === 'fade_from_black') {
            overlay.css({ opacity: '1', background: 'black', transition: `opacity ${duration}s` });
            setTimeout(() => overlay.css('opacity', '0'), 10);
            await new Promise(resolve => setTimeout(resolve, duration * 1000));
          }
          break;
      }
    } catch (error) {}
  }

  function showCharacter(messageId, name, position, spriteUrl) {
    const state = gameStates[messageId];
    if (!state) return;

    if (!spriteUrl && position && position !== 'L' && position !== 'C' && position !== 'R') {
      spriteUrl = position;
      for (const p in state.characters) {
        if (state.characters[p].name === name) { position = p; break; }
      }
    }
    if (!['L', 'C', 'R'].includes(position)) position = 'C';

    const pos = position === 'L' ? 'left' : position === 'C' ? 'center' : 'right';
    const charElement = $(`#char-${pos}-${messageId}`);
    if (!charElement.length) return;

    charElement.removeClass('dimmed');
    for (const p in state.characters) {
      if (p !== position && state.characters[p].name === name) {
        $(`#char-${p === 'L' ? 'left' : p === 'C' ? 'center' : 'right'}-${messageId}`).removeClass('active');
        state.characters[p] = { name: null, sprite: null };
      }
    }

    let actualSpriteUrl = resolveImageUrl(spriteUrl, 'char')?.url;
    if (actualSpriteUrl) {
      charElement.css({ 'max-height': '', 'max-width': '', 'bottom': '' });
      charElement.attr('src', actualSpriteUrl);
      charElement.css('display', 'block').addClass('active');
      state.characters[position] = { name: name, sprite: actualSpriteUrl };
    } else {
      charElement.removeClass('active');
      state.characters[position] = { name: name, sprite: null };
    }

    for (const p in state.characters) {
      if (p !== position && state.characters[p].name) {
        $(`#char-${p === 'L' ? 'left' : p === 'C' ? 'center' : 'right'}-${messageId}`).addClass('dimmed');
      }
    }
  }

  function hideCharacter(messageId, target) {
    const state = gameStates[messageId];
    if (!state) return;
    for (const p in state.characters) {
      if (p === target || state.characters[p].name === target) {
        $(`#char-${p === 'L' ? 'left' : p === 'C' ? 'center' : 'right'}-${messageId}`).removeClass('active dimmed');
        state.characters[p] = { name: null, sprite: null };
      }
    }
  }

  function hideAllCharacters(messageId) {
    $(`#char-left-${messageId}, #char-center-${messageId}, #char-right-${messageId}`).removeClass('active dimmed');
    if (gameStates[messageId]) gameStates[messageId].characters = { L: { name: null, sprite: null }, C: { name: null, sprite: null }, R: { name: null, sprite: null } };
  }

  function executeAction(messageId, targetName, actionType, params, isSkip = false) {
    const state = gameStates[messageId];
    if (!state) return;
    let targetElement = null; let pos = null;
    for (const p in state.characters) {
      if (state.characters[p].name === targetName || p === targetName) {
        pos = p === 'L' ? 'left' : p === 'C' ? 'center' : 'right';
        targetElement = $(`#char-${pos}-${messageId}`);
        break;
      }
    }
    if (!targetElement) return;

    if (isSkip) {
      if (actionType === 'near') {
         const nearTrans = pos === 'right' ? 'translateX(-50%) scaleX(-1) scale(calc(var(--char-scale, 1) * 1.08))' : 'translateX(-50%) scaleX(1) scale(calc(var(--char-scale, 1) * 1.08))';
         targetElement.css('transform', nearTrans);
      } else if (actionType === 'away') {
         const awayTrans = pos === 'right' ? 'translateX(-50%) scaleX(-1) scale(calc(var(--char-scale, 1) * 0.92))' : 'translateX(-50%) scaleX(1) scale(calc(var(--char-scale, 1) * 0.92))';
         targetElement.css('transform', awayTrans);
      }
      return;
    }

    targetElement.css('--originalScaleX', pos === 'right' ? -1 : 1);
    targetElement.removeClass(`shake-char-${messageId}`);
    void targetElement[0].offsetWidth;

    const baseTrans = pos === 'right' ? 'translateX(-50%) scaleX(-1) scale(var(--char-scale, 1))' : 'translateX(-50%) scaleX(1) scale(var(--char-scale, 1))';

    if (actionType === 'shake') {
      const origTrans = targetElement.css('transition');
      targetElement.css('transition', 'none').css('animation', `shake-char-${messageId} 0.5s ease-in-out`);
      setTimeout(() => targetElement.css('animation', '').css('transition', origTrans).css('transform', baseTrans), 500);
    } else if (actionType === 'jump_up') {
      targetElement.css('transition', 'transform 0.15s ease-out').css('transform', `translateY(-20px) ${baseTrans}`);
      setTimeout(() => { targetElement.css('transition', 'transform 0.15s ease-in').css('transform', baseTrans); }, 150);
    } else if (actionType === 'jump_down') {
      targetElement.css('transition', 'transform 0.15s ease-out').css('transform', `translateY(10px) ${baseTrans}`);
      setTimeout(() => { targetElement.css('transition', 'transform 0.15s ease-in').css('transform', baseTrans); }, 150);
    } else if (actionType === 'near') {
      const nearTrans = pos === 'right' ? 'translateX(-50%) scaleX(-1) scale(calc(var(--char-scale, 1) * 1.08))' : 'translateX(-50%) scaleX(1) scale(calc(var(--char-scale, 1) * 1.08))';
      targetElement.css('transition', 'transform 0.3s ease-out').css('transform', nearTrans);
    } else if (actionType === 'away') {
      const awayTrans = pos === 'right' ? 'translateX(-50%) scaleX(-1) scale(calc(var(--char-scale, 1) * 0.92))' : 'translateX(-50%) scaleX(1) scale(calc(var(--char-scale, 1) * 0.92))';
      targetElement.css('transition', 'transform 0.3s ease-out').css('transform', awayTrans);
    }
  }

  function typewriterEffect(messageId, text, onComplete) {
    const textEl = $(`#text-${messageId}`);
    const state = gameStates[messageId];

    enableNav(messageId);
    textEl.text('');
    if (!state) return;

    if (!text) {
      if (onComplete) onComplete();
      return;
    }

    const speedMs = config.typewriterSpeed;
    const charsPerMs = 1 / speedMs;

    state.isTypewriting = true;
    state.skipTypewriter = false;
    state.lastCharsToShow = 0;
    let startTime = null;

    state.typeFunction = function finishInstantly() {
      if (state.skipping) return;
      if (state.typeTimer) {
        cancelAnimationFrame(state.typeTimer);
        state.typeTimer = null;
      }
      textEl.text(text);
      state.isTypewriting = false;
      state.skipTypewriter = false;
      state.typeFunction = null;
      state.lastCharsToShow = 0;
      enableNav(messageId);
      addToHistory(messageId, $(`#name-${messageId}`).is(':visible') ? $(`#name-${messageId}`).text() : '', text);
      if (onComplete) onComplete();
      handleAutoNext(messageId);
    };

    function step(timestamp) {
      if (state.skipping) return;
      if (state.skipTypewriter || !state.processing) {
        state.typeFunction();
        return;
      }

      if (!startTime) startTime = timestamp;
      const elapsed = timestamp - startTime;
      const charsToShow = Math.floor(elapsed * charsPerMs);

      if (charsToShow < text.length) {
        if (charsToShow > state.lastCharsToShow) {
            if (textEl.length) textEl[0].textContent = text.substring(0, charsToShow);
            state.lastCharsToShow = charsToShow;
        }
        state.typeTimer = requestAnimationFrame(step);
      } else {
        state.typeFunction();
      }
    }

    state.typeTimer = requestAnimationFrame(step);
  }

  function addToHistory(messageId, speaker, text) {
    const state = gameStates[messageId];
    if (!state) return;
    if (!state.history) state.history = [];
    const speakerFmt = speaker ? `[${speaker}]` : '';
    const last = state.history[state.history.length - 1];
    if (last && last.speaker === speakerFmt && last.text === text) return;
    state.history.push({ speaker: speakerFmt, text });
    if (state.history.length > 100) state.history.shift();
    if (state.history.length === 1) {
      $(`#history-btn-${messageId}`).removeClass('locked');
    }
  }

  function showHistoryModal(messageId) {
    const state = gameStates[messageId];
    if (!state || !state.history) return;
    const list = $(`#history-list-${messageId}`);
    list.empty();
    state.history.forEach(item => {
      list.append(`<div class="galgame-history-item-${messageId}"><span class="galgame-history-speaker-${messageId}">${item.speaker}</span><span class="galgame-history-text-${messageId}">${item.text}</span></div>`);
    });
    $(`#history-modal-${messageId}`).css('display', 'block');
    const content = $(`#history-modal-${messageId} .galgame-history-content-${messageId}`);
    content.scrollTop(content[0].scrollHeight);
  }

  function hideHistoryModal(messageId) { $(`#history-modal-${messageId}`).css('display', 'none'); }

  function showCG(messageId, cgUrl) {
    const records = getCGUnlockRecord();
    let shouldShow = false;

    if (records[cgUrl] !== undefined) {
      if (records[cgUrl] === messageId) {
        shouldShow = true;
      }
    } else {
      records[cgUrl] = messageId;
      saveCGUnlockRecord(records);
      shouldShow = true;
    }

    if (!shouldShow) return;

    const cgEl = $(`#cg-${messageId}`);
    const actualCgUrl = resolveImageUrl(cgUrl, 'cg')?.url;
    if (actualCgUrl) {
      cgEl.find('img').attr('src', actualCgUrl);
      cgEl.addClass('active');
    }
  }

  function hideCG(messageId) { $(`#cg-${messageId}`).removeClass('active'); }

  async function setBackground(messageId, bgUrl, unused, duration = 0.5) {
    const bgEl = $(`#bg-${messageId}`);
    const actualBgUrl = resolveImageUrl(bgUrl, 'bg')?.url;
    bgEl.css('transition', `background-image ${duration}s ease`);
    if (actualBgUrl) {
      bgEl.css({ 'background-image': `url(${actualBgUrl})` });
    } else {
      bgEl.css({ 'background-image': 'none', 'background-color': '#000' });
    }
  }

  function finishStreamGeneration() {
    if (!streamInfo) return;
    window.GALGAME_FINISHING_STREAM = true;
    streamInfo.generationComplete = true;

    if (streamInfo.originalMessageEl) {
      streamInfo.originalMessageEl.children(`.galgame-hidden-original-${streamInfo.mesid}`)
        .css('display', '')
        .removeClass(`galgame-hidden-original-${streamInfo.mesid}`);
    }

    const finalStreamText = streamInfo.text;
    const mesid = streamInfo.mesid;

    if (tempMesText) {
      tempMesText.remove();
      tempMesText = null;
    }

    streamInfo = undefined;
    streamStart = false;
    streamParsing = false;

    renderedMessages.delete(mesid);
    delete gameStates[mesid];

    setTimeout(() => {
      renderGameForMessage(mesid, finalStreamText);
      setTimeout(() => {
        window.GALGAME_FINISHING_STREAM = false;
      }, 100);
    }, 50);
  }

  async function streamParser(fulltext) {
    try {
      if (!streamStart) {
        streamStart = true; streamParsing = false;
        let last_mesid = getLatestMessageIdSafe();
        let mes_text = getSafeMessageElement(last_mesid);
        if (!mes_text || !mes_text.length) { streamStart = false; return; }

        streamInfo = {
          mesid: last_mesid, textLength: fulltext.length, text: fulltext, textCount: 0,
          characters: { L: { name: null, sprite: null }, C: { name: null, sprite: null }, R: { name: null, sprite: null } },
          currentDialogIndex: 0, dialogues: [], waitingForClick: true, history: [], isComplete: false, originalMessageEl: mes_text,
        };

        mes_text.children().not('.roleplay_galgame_temp').css('display', 'none').addClass(`galgame-hidden-original-${last_mesid}`);

        tempMesText = $('<div class="roleplay_galgame_temp" style="width: 100%;"></div>');
        mes_text.append(tempMesText);

        const gameHTML = createGameHTML(last_mesid, { scenes: [] });
        tempMesText.append(gameHTML);

        $(`.galgame-char-${last_mesid}`, tempMesText).on('error', function() {
          $(this).attr('src', EMPTY_IMAGE).removeClass('active');
        });
        $(`.galgame-cg-${last_mesid} img`, tempMesText).on('error', function() {
          $(this).attr('src', EMPTY_IMAGE);
          $(this).parent().removeClass('active');
        });

        $(`.galgame-container-${last_mesid}`, tempMesText).on('click', function(e) {
          if ($(e.target).closest('.galgame-history-modal-' + last_mesid).length ||
              $(e.target).closest('.galgame-cg-modal-' + last_mesid).length ||
              $(e.target).closest('.galgame-cg-viewer-' + last_mesid).length ||
              $(e.target).closest('.galgame-choices-' + last_mesid).length ||
              $(e.target).closest(`.gsm-status-panel-${last_mesid}`).length ||
              $(e.target).closest(`.gsm-overlay-mask-${last_mesid}`).length ||
              $(e.target).closest(`.gsm-hidden-checkbox-${last_mesid}`).length ||
              $(e.target).closest(`.galgame-bgm-panel-${last_mesid}`).length ||
              $(e.target).closest(`.galgame-display-panel-${last_mesid}`).length ||
              $(e.target).closest(`.galgame-controls-wrapper-${last_mesid}`).length) return;
          e.stopPropagation();
          if (streamInfo.processing || streamInfo.showingChoices) {
            if (streamInfo.typeTimer) {
              clearTimeout(streamInfo.typeTimer);
              streamInfo.typeTimer = null;
              streamInfo.textElement.html(streamInfo.currentFullText);
              enableNav(last_mesid);
              streamInfo.processing = false;
            }
            return;
          }
          processStreamNextDialogue();
        });

        $(`.galgame-history-btn-${last_mesid}`, tempMesText).on('click', e => { e.stopPropagation(); showStreamHistoryModal(last_mesid); });
        $(`.galgame-history-close-${last_mesid}`, tempMesText).on('click', e => { e.stopPropagation(); hideStreamHistoryModal(last_mesid); });

        streamInfo.nameElement = $(`#name-${last_mesid}`, tempMesText);
        streamInfo.textElement = $(`#text-${last_mesid}`, tempMesText);
        streamInfo.sceneElement = $(`#bg-${last_mesid}`, tempMesText);
        streamInfo.leftCharElement = $(`#char-left-${last_mesid}`, tempMesText);
        streamInfo.centerCharElement = $(`#char-center-${last_mesid}`, tempMesText);
        streamInfo.rightCharElement = $(`#char-right-${last_mesid}`, tempMesText);
        streamInfo.cgElement = $(`#cg-${last_mesid}`, tempMesText);
        streamInfo.choicesElement = $(`#choices-${last_mesid}`, tempMesText);
        streamInfo.overlayElement = $(`#overlay-${last_mesid}`, tempMesText);
        streamInfo.historyListElement = $(`#history-list-${last_mesid}`, tempMesText);

        streamInfo.nameElement.hide(); disableNav(last_mesid);
        streamParsing = false; processStreamContent(fulltext);
      } else if (!streamParsing && streamInfo) {
        streamParsing = true;
        const incText = fulltext.slice(streamInfo.textLength);
        if (!incText.length) { streamParsing = false; return; }
        streamInfo.text += incText; streamInfo.textLength = streamInfo.text.length;

        if (incText.includes('</gametext>') || incText.includes('```')) {
          streamInfo.isComplete = true;
          if (!window.GALGAME_EDITING_MESSAGE) {
            setTimeout(() => finishStreamGeneration(), 100);
          }
        }
        processStreamContent(streamInfo.text);
        streamParsing = false;
      }
    } catch (e) { streamParsing = false; }
  }

  function processStreamContent(content) {
    if (!streamInfo || !tempMesText) return;
    let scriptText = content;

    const contentMatch = content.match(/<content>[\s\S]*?<gametext>([\s\S]*?)(?:<\/gametext>|$)[\s\S]*?(?:<\/content>|$)/i);
    const gMatch = content.match(/<gametext>([\s\S]*?)(?:<\/gametext>|$)/i);

    if (contentMatch) {
      scriptText = contentMatch[1];
    } else if (gMatch) {
      scriptText = gMatch[1];
    } else {
      const fallbackMatch = content.match(/```(?:galgame)?\n([\s\S]*?)(?:```|$)/i);
      if (fallbackMatch) {
        scriptText = fallbackMatch[1];
      }
    }

    scriptText = scriptText.replace(/\[[^\]]*$/g, '');
    const lines = scriptText.split('\n');
    streamInfo.dialogues = [];

    for (const line of lines) {
      const t = line.trim();
      if (!t) continue;
      const diagMatch = t.match(dialogueRegex);
      if (diagMatch) {
        let text = diagMatch[4].trim().replace(/\[[^\]]*$/g, '').replace(/^[^\[]*\]/g, '');
        let inlineAction = null;
        const actMatch = text.match(/(\[action\|.+?\])$/);
        if (actMatch) {
          text = text.replace(actMatch[0], '').trim();
          const parts = actMatch[1].replace(/^\[|\]$/g, '').split('|');
          inlineAction = { target: parts[1]?.trim(), action: parts[2]?.trim(), params: parts.slice(3).map(p => p.trim()) };
        }
        streamInfo.dialogues.push({ type: 'dialogue', character: diagMatch[1].trim() || '旁白', position: diagMatch[2].trim().toUpperCase() || null, sprite: diagMatch[3].trim(), text: text, inlineAction: inlineAction });
        continue;
      }
      const cmdMatch = t.match(commandRegex);
      if (cmdMatch) {
        const parts = cmdMatch[1].split('|');
        streamInfo.dialogues.push({ type: 'command', command: parts[0].trim(), args: parts.slice(1).map(x => x.trim()) });
      }
    }
    streamInfo.textCount = streamInfo.dialogues.length;
    if (streamInfo.dialogues.length > 0 && !streamInfo.initialized) { streamInfo.initialized = true; processStreamNextDialogue(); }
  }

  function processStreamNextDialogue() {}

  function scanAllMesIds() {
    const ids = [];
    $('.mes[mesid]').each(function() {
      const id = $(this).attr('mesid');
      if (id) ids.push(id);
    });
    return ids;
  }

  async function scanAndRenderAllMessages() {
    const allIds = scanAllMesIds();
    for (const msgId of allIds) {
      if (!renderedMessages.has(msgId)) {
        await renderGameForMessage(msgId);
      }
    }
  }

  function setupEventListeners() {
    let updateDebounceTimer = null;

    eventOn(tavern_events.MESSAGE_EDITED, msgId => {
      const numId = Number(msgId);
      const messageElement = getSafeMessageElement(numId);

      messageElement.children(`.galgame-hidden-original-${numId}`)
        .css('display', '')
        .removeClass(`galgame-hidden-original-${numId}`);

      messageElement.find('.roleplay_galgame_wrapper').remove();

      renderedMessages.delete(numId);
      delete gameStates[numId];
    });

    eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, async msgId => {
      if (!window.GALGAME_FINISHING_STREAM) await renderGameForMessage(Number(msgId));
    });

    if (typeof tavern_events !== 'undefined' && tavern_events.MESSAGE_DELETED) {
      eventOn(tavern_events.MESSAGE_DELETED, msgId => {
        const numId = Number(msgId);
        renderedMessages.delete(numId);
        renderingInProgress.delete(numId);
        if (gameStates[numId]) {
            if (gameStates[numId].typeTimer) cancelAnimationFrame(gameStates[numId].typeTimer);
            if (gameStates[numId].autoTimer) clearTimeout(gameStates[numId].autoTimer);
            delete gameStates[numId];
        }
      });
    }

    eventOn(tavern_events.MESSAGE_UPDATED, async msgId => {
      const numId = Number(msgId);

      if (streamStart) return;
      if (window.GALGAME_FINISHING_STREAM) return;
      if ($('.edit_textarea').is(':visible')) return;

      if (updateDebounceTimer) clearTimeout(updateDebounceTimer);
      updateDebounceTimer = setTimeout(async () => {
        if (renderedMessages.has(numId)) {
          renderedMessages.delete(numId);
          delete gameStates[numId];
        }
        await renderGameForMessage(numId);
      }, 300);
    });

    eventOn(tavern_events.CHAT_CHANGED, async () => {
      chatChangedHandled = true;
      renderedMessages.clear();
      renderingInProgress.clear();
      Object.keys(gameStates).forEach(k => {
          if (gameStates[k].typeTimer) cancelAnimationFrame(gameStates[k].typeTimer);
          if (gameStates[k].autoTimer) clearTimeout(gameStates[k].autoTimer);
          delete gameStates[k];
      });
      streamInfo = undefined; streamStart = false;
      if (tempMesText) { tempMesText.remove(); tempMesText = null; }

      if (window.__GAL_BGM_AUDIO__) {
          window.__GAL_BGM_AUDIO__.pause();
          window.__GAL_BGM_AUDIO__.src = '';
      }

      await new Promise(resolve => setTimeout(resolve, 400));
      await scanAndRenderAllMessages();
    });

    eventOn(tavern_events.STREAM_TOKEN_RECEIVED, streamParser);

    eventOn(tavern_events.MESSAGE_RECEIVED, async (msgId) => {
      const numId = Number(msgId);
      setTimeout(async () => {
        if (!window.GALGAME_FINISHING_STREAM) {
          if (!renderedMessages.has(numId)) await renderGameForMessage(numId);
        }
      }, 600);
    });

    eventOn(tavern_events.GENERATION_ENDED, async () => {
      setTimeout(async () => {
        if (streamStart && streamInfo && !streamInfo.isComplete) {
          streamInfo.isComplete = true;
          finishStreamGeneration();
        } else {
          let last_mesid = getLatestMessageIdSafe();
          if (last_mesid > 0) {
            const messageElement = getSafeMessageElement(last_mesid);
            const wrapper = messageElement.find('.roleplay_galgame_wrapper');
            const isOriginalVisible = messageElement.children().not('.roleplay_galgame_wrapper').is(':visible');

            if (wrapper.length === 0 || isOriginalVisible) {
              log('检测到界面丢失，触发兜底重绘机制', last_mesid);

              renderedMessages.delete(last_mesid);
              renderingInProgress.delete(last_mesid);
              delete gameStates[last_mesid];

              await renderGameForMessage(last_mesid);
            } else if (!renderedMessages.has(last_mesid) && !renderingInProgress.has(last_mesid)) {
              await renderGameForMessage(last_mesid);
            }
          }
        }
      }, 800);
    });

    eventOn(tavern_events.GENERATION_STOPPED, () => {
      if (streamInfo && !streamInfo.isComplete) {
        streamInfo.isComplete = true;
        finishStreamGeneration();
      }
    });

    if (typeof Mvu !== 'undefined' && Mvu.events) {
        const mvuUpdateHandler = (variables) => {
            const latestId = getLatestMessageIdSafe();
            if (gameStates[latestId] && gameStates[latestId].updateStatus) {
                gameStates[latestId].updateStatus(variables);
            }
        };
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, mvuUpdateHandler);
        eventOn(Mvu.events.VARIABLE_INITIALIZED, mvuUpdateHandler);
    } else {
        const mvuUpdateHandler = (variables) => {
            const latestId = getLatestMessageIdSafe();
            if (gameStates[latestId] && gameStates[latestId].updateStatus) {
                gameStates[latestId].updateStatus(variables);
            }
        };
        eventOn('mag_variable_update_ended', mvuUpdateHandler);
        eventOn('mag_variable_initiailized', mvuUpdateHandler);
    }
  }

  $(async function () {
    setupEventListeners();
    await new Promise(resolve => setTimeout(resolve, 800));
    if (!chatChangedHandled) {
      await scanAndRenderAllMessages();
    }
  });

})();
